# Configure-EndpointAppLocker.ps1 # Description: Configures the Application Identity service (AppIDSvc) to start automatically and imports a robust AppLocker XML policy.
Write-Host "Applying AppLocker Identity service hardening..." -ForegroundColor Cyan
# 1. Enable Application Identity service (AppIDSvc) $AppLockerService = Get-Service -Name AppIDSvc -ErrorAction SilentlyContinue if ($AppLockerService) { Set-Service -Name AppIDSvc -StartupType Automatic Start-Service -Name AppIDSvc -ErrorAction SilentlyContinue Write-Host "[+] Application Identity Service (AppIDSvc) set to Automatic and started." -ForegroundColor Green } else { Write-Warning "[-] Application Identity Service not found on this machine." }
# 2. Configure local AppLocker policy XML content $AppLockerXml = @" <AppLockerPolicy Version="1"> <RuleCollection Type="Exe" EnforcementMode="Enabled"> <FilePathRule Id="921cc481-6e1e-453f-b3a5-bc4f4a38674d" Name="(Default Rule) All files located in the Program Files folder" Description="Allows members of the Everyone group to run applications that are located in the Program Files folder." UserOrGroupSid="S-1-1-0" Action="Allow"> <Conditions> <FilePathCondition Path="%PROGRAMFILES%\*" /> </Conditions> </FilePathRule> <FilePathRule Id="a61c8b2c-6d8f-4ad9-acbc-467b78a7f7b4" Name="(Default Rule) All files located in the Windows folder" Description="Allows members of the Everyone group to run applications that are located in the Windows folder." UserOrGroupSid="S-1-1-0" Action="Allow"> <Conditions> <FilePathCondition Path="%WINDIR%\*" /> </Conditions> <Exceptions> <FilePathCondition Path="%WINDIR%\Temp\*" /> <FilePathCondition Path="%WINDIR%\Tasks\*" /> <FilePathCondition Path="%WINDIR%\tracing\*" /> <FilePathCondition Path="%WINDIR%\System32\spool\drivers\color\*" /> <FilePathCondition Path="%WINDIR%\System32\Tasks\Microsoft\Windows\SyncCenter\*" /> <FilePathCondition Path="%WINDIR%\SysWOW64\Tasks\Microsoft\Windows\SyncCenter\*" /> <FilePathCondition Path="*\msbuild.exe" /> <FilePathCondition Path="*\installutil.exe" /> <FilePathCondition Path="*\mshta.exe" /> <FilePathCondition Path="*\regasm.exe" /> <FilePathCondition Path="*\regsvcs.exe" /> <FilePathCondition Path="*\regsvr32.exe" /> <FilePathCondition Path="*\rundll32.exe" /> <FilePathCondition Path="*\bginfo.exe" /> <FilePathCondition Path="*\cdb.exe" /> <FilePathCondition Path="*\cmstp.exe" /> <FilePathCondition Path="*\control.exe" /> <FilePathCondition Path="*\csi.exe" /> <FilePathCondition Path="*\dfsvc.exe" /> <FilePathCondition Path="*\dnx.exe" /> <FilePathCondition Path="*\fsi.exe" /> <FilePathCondition Path="*\ie4unit.exe" /> <FilePathCondition Path="*\ieexec.exe" /> <FilePathCondition Path="*\infdefaultinstall.exe" /> <FilePathCondition Path="*\mavinject.exe" /> <FilePathCondition Path="*\msdeploy.exe" /> <FilePathCondition Path="*\msdt.exe" /> <FilePathCondition Path="*\msxsl.exe" /> <FilePathCondition Path="*\odbcconf.exe" /> <FilePathCondition Path="*\presentationhost.exe" /> <FilePathCondition Path="*\rcsi.exe" /> <FilePathCondition Path="*\rsi.exe" /> <FilePathCondition Path="*\runscripthelper.exe" /> <FilePathCondition Path="*\te.exe" /> <FilePathCondition Path="*\tracker.exe" /> <FilePathCondition Path="*\xwizard.exe" /> </Exceptions> </FilePathRule> <FilePathRule Id="fd686d83-a829-4351-8ff4-27c1de5732e9" Name="(Default Rule) All files" Description="Allows members of the local Administrators group to run all applications." UserOrGroupSid="S-1-5-32-544" Action="Allow"> <Conditions> <FilePathCondition Path="*" /> </Conditions> </FilePathRule> </RuleCollection> <RuleCollection Type="Msi" EnforcementMode="Enabled"> <FilePathRule Id="5b8fa8b3-3a5e-4c7a-9cb8-b223ff9db271" Name="(Default Rule) All Windows Installer files in Program Files" Description="Allows everyone to run Windows Installer files in Program Files." UserOrGroupSid="S-1-1-0" Action="Allow"> <Conditions> <FilePathCondition Path="%PROGRAMFILES%\*" /> </Conditions> </FilePathRule> <FilePathRule Id="6b8fa8b3-3a5e-4c7a-9cb8-b223ff9db272" Name="(Default Rule) All Windows Installer files in Windows" Description="Allows everyone to run Windows Installer files in Windows." UserOrGroupSid="S-1-1-0" Action="Allow"> <Conditions> <FilePathCondition Path="%WINDIR%\*" /> </Conditions> </FilePathRule> <FilePathRule Id="7b8fa8b3-3a5e-4c7a-9cb8-b223ff9db273" Name="(Default Rule) All Windows Installer files" Description="Allows administrators to run all Windows Installer files." UserOrGroupSid="S-1-5-32-544" Action="Allow"> <Conditions> <FilePathCondition Path="*" /> </Conditions> </FilePathRule> </RuleCollection> <RuleCollection Type="Script" EnforcementMode="Enabled"> <FilePathRule Id="1c8fa8b3-3a5e-4c7a-9cb8-b223ff9db274" Name="(Default Rule) All scripts located in the Program Files folder" Description="Allows everyone to run scripts in Program Files." UserOrGroupSid="S-1-1-0" Action="Allow"> <Conditions> <FilePathCondition Path="%PROGRAMFILES%\*" /> </Conditions> </FilePathRule> <FilePathRule Id="2c8fa8b3-3a5e-4c7a-9cb8-b223ff9db275" Name="(Default Rule) All scripts located in the Windows folder" Description="Allows everyone to run scripts in Windows." UserOrGroupSid="S-1-1-0" Action="Allow"> <Conditions> <FilePathCondition Path="%WINDIR%\*" /> </Conditions> <Exceptions> <FilePathCondition Path="%WINDIR%\Temp\*" /> <FilePathCondition Path="%WINDIR%\Tasks\*" /> </Exceptions> </FilePathRule> <FilePathRule Id="3c8fa8b3-3a5e-4c7a-9cb8-b223ff9db276" Name="(Default Rule) All scripts" Description="Allows administrators to run all scripts." UserOrGroupSid="S-1-5-32-544" Action="Allow"> <Conditions> <FilePathCondition Path="*" /> </Conditions> </FilePathRule> </RuleCollection> <RuleCollection Type="Appx" EnforcementMode="Enabled"> <FilePublisherRule Id="1d8fa8b3-3a5e-4c7a-9cb8-b223ff9db279" Name="(Default Rule) All signed packaged apps" Description="Allows everyone to run signed packaged apps." UserOrGroupSid="S-1-1-0" Action="Allow"> <Conditions> <FilePublisherCondition PublisherName="*" ProductName="*" BinaryName="*"> <BinaryVersionRange LowSection="0.0.0.0" HighSection="*" /> </FilePublisherCondition> </Conditions> </FilePublisherRule> </RuleCollection> </AppLockerPolicy> "@
# Write the temporary XML and import it $TempPath = Join-Path -Path $env:TEMP -ChildPath "AppLockerEndpointPolicy.xml" $AppLockerXml | Out-File -FilePath $TempPath -Encoding UTF8 -Force
# 3. Validate policy using Test-AppLockerPolicy before importing try { Import-Module AppLocker -ErrorAction Stop } catch { Write-Error "AppLocker module is not available on this system. Cannot configure or validate policy." if (Test-Path $TempPath) { Remove-Item -Path $TempPath -Force } return }
$TestPaths = @( # Expected: Allowed "$env:windir\System32\cmd.exe", "$env:windir\System32\WindowsPowerShell\v1.0\powershell.exe", # Expected: DeniedByDefault or ExplicitlyDenied (since it is an exception to an Allow rule) "$env:USERPROFILE\Downloads\tool.exe", "$env:windir\Temp\malware.exe", "$env:windir\Tasks\evil.exe", "$env:windir\System32\msbuild.exe" )
$ValidationFailed = $false try { $TestResults = Test-AppLockerPolicy -XmlPolicy $TempPath -Path $TestPaths -User Everyone -ErrorAction Stop $ExpectedAllow = @( "$env:windir\System32\cmd.exe", "$env:windir\System32\WindowsPowerShell\v1.0\powershell.exe" ) $ExpectedDeny = @( "$env:USERPROFILE\Downloads\tool.exe", "$env:windir\Temp\malware.exe", "$env:windir\Tasks\evil.exe", "$env:windir\System32\msbuild.exe" )
foreach ($Result in $TestResults) { $Path = $Result.FilePath $Decision = $Result.PolicyDecision if ($ExpectedAllow -contains $Path) { if ($Decision -ne "Allowed") { Write-Warning "[VALIDATION FAIL] Expected Allow for: $Path (got: $Decision)" $ValidationFailed = $true } } if ($ExpectedDeny -contains $Path) { if ($Decision -eq "Allowed") { Write-Warning "[VALIDATION FAIL] Expected Deny/Not Allowed for: $Path (got: $Decision)" $ValidationFailed = $true } } } } catch { Write-Warning "Could not perform policy validation tests: $($_.Exception.Message)" $ValidationFailed = $true }
if ($ValidationFailed) { Write-Error "AppLocker policy validation failed. Policy was NOT imported." if (Test-Path $TempPath) { Remove-Item -Path $TempPath -Force } return }
Write-Host "[+] AppLocker policy validation passed. Proceeding with import." -ForegroundColor Green
# 4. Import the validated AppLocker policy try { Set-AppLockerPolicy -XmlPolicy $TempPath -ErrorAction Stop Write-Host "[+] Local AppLocker policy imported and enforced successfully." -ForegroundColor Green } catch { Write-Error "Failed to import AppLocker policy: $($_.Exception.Message)" } finally { if (Test-Path $TempPath) { Remove-Item -Path $TempPath -Force } }
# 5. Disable NTVDM (16-bit compatibility) via Registry $NtvdmPath = "HKLM:\SOFTWARE\Policies\Microsoft\Windows\AppCompat" if (-not (Test-Path $NtvdmPath)) { New-Item -Path $NtvdmPath -Force | Out-Null } Set-ItemProperty -Path $NtvdmPath -Name "Prevent16BitApp" -Value 1 -Type DWord Write-Host "[+] 16-bit NTVDM compatibility disabled in registry." -ForegroundColor Green

# Disable-UnusedFeatures.ps1
# Description: Disables unused legacy features, .NET 3.5, and PowerShell 2.0 on the local system.

Write-Host "Disabling unused legacy features and PowerShell 2.0..." -ForegroundColor Cyan

# Check if running as administrator
$isAdmin = ([Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
if (-not $isAdmin) {
    Write-Error "This script must be run as an Administrator."
    exit 1
}

# Feature lists
$DismFeatures = @(
    "MicrosoftWindowsPowerShellV2",
    "MicrosoftWindowsPowerShellV2Root",
    "NetFx3",                                # .NET Framework 3.5
    "SMB1Protocol",                          # SMBv1 Client
    "Internet-Explorer-Optional-amd64",      # Internet Explorer 11
    "WorkFolders-Client",                    # Work Folders Client
    "Xps-Viewer-Dependency",                 # XPS Viewer
    "DirectPlay",                            # DirectPlay
    "TelnetClient",                          # Telnet Client
    "TFTP",                                  # TFTP Client
    "SimpleTCP"                              # Simple TCP/IP Services
)

$ServerFeatures = @(
    "PowerShell-V2",
    "NET-Framework-Core",
    "FS-SMB1",
    "Internet-Explorer-Optional-amd64",
    "WorkFolders-Client",
    "Xps-Viewer-Dependency",
    "DirectPlay",
    "Telnet-Client",
    "TFTP-Client",
    "Simple-TCPIP"
)

if (Get-Command Get-WindowsFeature -ErrorAction SilentlyContinue) {
    # Windows Server path
    foreach ($FeatName in $ServerFeatures) {
        $Feat = Get-WindowsFeature -Name $FeatName -ErrorAction SilentlyContinue
        if ($null -ne $Feat) {
            if ($Feat.Installed) {
                Write-Host "[*] Removing Server feature: $FeatName..." -ForegroundColor Yellow
                Uninstall-WindowsFeature -Name $FeatName -ErrorAction SilentlyContinue | Out-Null
                Write-Host "[+] Feature '$FeatName' uninstalled." -ForegroundColor Green
            } else {
                Write-Host "[~] Feature '$FeatName' is already uninstalled." -ForegroundColor Gray
            }
        } else {
            # Try DISM fallback
            $DismFeat = Get-WindowsOptionalFeature -Online -FeatureName $FeatName -ErrorAction SilentlyContinue
            if ($null -ne $DismFeat) {
                if ($DismFeat.State -eq "Enabled" -or $DismFeat.State -eq "EnabledPendingRestart") {
                    Write-Host "[*] Disabling optional feature: $FeatName..." -ForegroundColor Yellow
                    Disable-WindowsOptionalFeature -Online -FeatureName $FeatName -NoRestart -ErrorAction SilentlyContinue | Out-Null
                    Write-Host "[+] Feature '$FeatName' disabled." -ForegroundColor Green
                } else {
                    Write-Host "[~] Feature '$FeatName' is already disabled." -ForegroundColor Gray
                }
            } else {
                Write-Host "[~] Feature '$FeatName' is not present in the system." -ForegroundColor Gray
            }
        }
    }
} else {
    # Windows Client path
    foreach ($Feature in $DismFeatures) {
        $State = Get-WindowsOptionalFeature -Online -FeatureName $Feature -ErrorAction SilentlyContinue
        if ($null -ne $State) {
            if ($State.State -eq "Enabled" -or $State.State -eq "EnabledPendingRestart") {
                Write-Host "[*] Disabling feature: $Feature..." -ForegroundColor Yellow
                Disable-WindowsOptionalFeature -Online -FeatureName $Feature -NoRestart -ErrorAction SilentlyContinue | Out-Null
                Write-Host "[+] Feature '$Feature' has been disabled." -ForegroundColor Green
            } else {
                Write-Host "[~] Feature '$Feature' is already disabled." -ForegroundColor Gray
            }
        } else {
            Write-Host "[~] Feature '$Feature' is not present in this Windows image." -ForegroundColor Gray
        }
    }
}

Write-Host "Optional features configuration completed." -ForegroundColor Green
